<script setup>
import {computed,ref,watch} from 'vue'
import {visualRows,visualSummary,caseExcerpt} from '../visual-results.js'
import WorkspaceIcon from './WorkspaceIcon.vue'
import WorkspaceDrawer from './WorkspaceDrawer.vue'
const props=defineProps({view:Object,modelValue:String,canModify:Boolean})
const emit=defineEmits(['update:modelValue','inspect-case'])
const filter=ref('all'),panel=ref(''),detailTab=ref('answer')
const summary=computed(()=>visualSummary(props.view)),rows=computed(()=>visualRows(props.view))
const selected=computed(()=>rows.value.find(c=>c.case_id===props.modelValue)||rows.value[0])
const visible=computed(()=>rows.value.filter(c=>filter.value==='all'||c.tone===filter.value))
const snippet=computed(()=>caseExcerpt(props.view,selected.value))
const groups=computed(()=>[{id:'all',label:'全部',count:summary.value.total},...['fail','error','unknown','pass','neutral'].map(id=>({id,label:{fail:summary.value.verified?'不通过':'未找到',error:'执行失败',unknown:'待确认',pass:summary.value.verified?'通过':'已找到',neutral:'不适用'}[id],count:summary.value.counts[id]})).filter(g=>g.id==='all'||g.count)])
const panelTitles={evidence:'原文与依据',logs:'本题运行日志',modify:'选择本题修改方式',review:'人工复核与问题记录',suggest:'生成优化建议',checks:'本次检查',metrics:'检索指标与用量',records:'原始记录与导出'}
function choose(id){emit('update:modelValue',id)}
function applyFilter(id){filter.value=id;if(!visible.value.some(c=>c.case_id===selected.value?.case_id))choose(visible.value[0]?.case_id||rows.value[0]?.case_id)}
function open(kind,tab='answer'){panel.value=kind;detailTab.value=tab}
watch(()=>props.view?.run.run_id,()=>{filter.value='all';panel.value=''})
function inspectCase(id){choose(id);panel.value='';filter.value='all'}
defineExpose({open,inspectCase})
const sourceNames=computed(()=>[...new Set((selected.value?.results||[]).map(r=>props.view.run.controls?.knowledge_snapshot?.documents?.find(d=>d.document_id===r.document_id)?.title||r.document_id))])
</script>
<template>
 <section class="visual-results" aria-label="评测结果概览">
  <div class="visual-overview"><div><h1>{{summary.title}}</h1><p>{{summary.total}} 道题<span v-if="!summary.verified"> · 仅检查资料查找</span><span v-else-if="summary.counts.error"> · {{summary.counts.error}} 道执行失败</span><span v-if="summary.counts.unknown"> · {{summary.counts.unknown}} 道待确认</span></p></div><div class="visual-ratio"><span>{{summary.verified?'通过':'找到'}} <strong>{{summary.passed}} / {{summary.binary}}</strong></span><small>{{summary.verified?'已判定':'已检查'}} {{summary.decided}} / {{summary.total}}</small></div></div>
  <div class="visual-result-bar" role="img" :aria-label="groups.filter(g=>g.id!=='all').map(g=>g.label+' '+g.count+' 道').join('，')"><span v-for="row in rows" :key="row.case_id" :class="'tone-'+row.tone" :title="'第'+row.number+'题 · '+row.status" /></div>
  <div class="visual-result-filters" aria-label="筛选评测状态"><button v-for="g in groups" :key="g.id" type="button" :aria-pressed="filter===g.id" @click="applyFilter(g.id)"><span v-if="g.id!=='all'" :class="['status-dot','tone-'+g.id]" />{{g.label}} {{g.count}}</button></div>
  <p v-if="summary.verified&&summary.decided<summary.total" class="visual-scope-note">通过率只计已判定题；其余题保留在本批记录中。</p>
  <p v-if="summary.historical" class="note warning">历史记录缺少完整统计范围，请核对原始记录。</p>
  <div class="visual-question-nav"><strong>第 {{selected?.number||'—'}} 题 <span>/ {{summary.total}}</span></strong><nav aria-label="题目导航"><button v-for="row in visible" :key="row.case_id" type="button" :title="row.query" :aria-label="'第'+row.number+'题，'+row.status" :aria-pressed="row.case_id===selected?.case_id" :class="{'active':row.case_id===selected?.case_id}" @click="choose(row.case_id)"><WorkspaceIcon :name="row.tone==='pass'?'check':row.tone==='error'?'alert':'minus'" :size="14" />{{row.number}}</button></nav></div>
  <article v-if="selected" class="visual-case" :data-testid="'retrieval-case-'+selected.case_id">
   <div class="visual-case-heading"><span :class="['visual-status','text-'+selected.tone]"><WorkspaceIcon :name="selected.tone==='error'?'alert':selected.tone==='pass'?'check':'minus'" :size="16" />{{selected.status}}</span><small>{{summary.verified?'回答评测':'资料查找'}}</small></div>
   <h2>{{selected.query}}</h2>
   <p class="visual-reason"><small>判定理由节选</small>{{snippet.reasonExcerpt}}</p>
   <div class="visual-evidence-flow">
    <button type="button" class="visual-flow-item" @click="open('evidence','source')"><span class="visual-flow-art"><WorkspaceIcon name="search" :size="27" /><WorkspaceIcon class="art-document" name="document" :size="20" /></span><span><small>当时查到的资料</small><strong>{{selected.results?.length||0}} 条资料</strong><span class="visual-source-names">{{sourceNames.slice(0,2).join('、')||'没有返回资料'}}{{sourceNames.length>2?' 等':''}}</span></span></button>
    <WorkspaceIcon class="visual-flow-arrow" name="arrow" />
    <button type="button" class="visual-flow-item" @click="open('evidence','answer')"><span class="visual-flow-art"><WorkspaceIcon name="chat" :size="29" /></span><span><small>回答原文节选</small><strong class="visual-answer-excerpt">{{snippet.answerExcerpt}}</strong></span></button>
   </div>
   <div class="visual-main-actions"><button type="button" class="secondary" @click="open('evidence')"><WorkspaceIcon name="document" :size="17" />看原文与依据</button><button v-if="selected.tone==='error'||selected.missing" type="button" class="primary" @click="open('logs')">查失败原因 <WorkspaceIcon name="arrow" :size="17" /></button><button v-else-if="canModify" type="button" class="primary" @click="open('modify')">记录一个改法 <WorkspaceIcon name="arrow" :size="17" /></button></div>
   <div class="visual-case-tools"><button type="button" @click="open('review')">人工复核</button><button v-if="canModify" type="button" @click="open('suggest')">优化建议</button><button type="button" @click="open('logs')">运行日志</button></div>
  </article>
  <p v-else class="empty">尚无题目结果，运行结束后查看。</p>
  <div class="visual-result-tools"><button type="button" @click="open('checks')"><WorkspaceIcon name="list" :size="17" />本次检查</button><button type="button" @click="open('metrics')"><WorkspaceIcon name="chart" :size="17" />指标与用量</button><button type="button" @click="open('records')"><WorkspaceIcon name="database" :size="17" />原始记录与导出</button></div>
  <WorkspaceDrawer :open="!!panel" :title="panelTitles[panel]||'查看记录'" @close="panel=''">
   <template v-if="panel==='evidence'"><div class="drawer-tabs" role="tablist" aria-label="单题材料"><button v-for="t in [{id:'answer',label:'原回答'},{id:'source',label:'参考依据'},{id:'reason',label:'评分与理由'}]" :key="t.id" type="button" role="tab" :aria-selected="detailTab===t.id" @click="detailTab=t.id">{{t.label}}</button></div><slot :name="detailTab" :row="selected" /></template>
   <slot v-else-if="panel==='checks'" name="checks" :inspect="inspectCase" />
   <slot v-else :name="panel" :row="selected" />
  </WorkspaceDrawer>
 </section>
</template>
<style scoped>
.visual-overview{display:flex;justify-content:space-between;align-items:center;gap:24px}.visual-overview h1{font-size:29px;letter-spacing:-.6px;line-height:1.4;margin:0}.visual-overview p{font-size:13px;color:var(--muted);margin:8px 0 0}.visual-ratio{display:grid;gap:3px;flex-shrink:0;text-align:right;font-size:13px;color:var(--muted)}.visual-ratio strong{font-size:25px;color:var(--color-text);font-weight:600;margin-left:6px}.visual-ratio small{font-size:12px}.visual-result-bar{display:flex;gap:5px;height:13px;margin:22px 0 12px}.visual-result-bar>span{flex:1;border-radius:3px;min-width:1px}.tone-pass{background:#718975}.tone-fail{background:#ca7868}.tone-error{background:repeating-linear-gradient(120deg,#d8af55 0 4px,#ecd9af 4px 7px)}.tone-unknown{background:#b4b9b0}.tone-neutral{background:#e0e3dc}.visual-result-filters{display:flex;flex-wrap:wrap;gap:18px}.visual-result-filters button{display:flex;align-items:center;gap:7px;background:none;border:0;font-size:12px;padding:4px 0;color:var(--muted)}.visual-result-filters button[aria-pressed=true]{color:var(--color-text);box-shadow:0 1px 0 currentColor}.status-dot{width:7px;height:7px;border-radius:50%}.visual-scope-note{font-size:11px;color:var(--muted);margin:10px 0 0}.visual-question-nav{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:18px 0 12px}.visual-question-nav>strong{font-size:12px;font-weight:500;white-space:nowrap}.visual-question-nav>strong>span{color:var(--muted)}.visual-question-nav nav{display:flex;flex-wrap:wrap;gap:6px}.visual-question-nav button{display:flex;align-items:center;justify-content:center;gap:4px;min-width:40px;min-height:34px;border:1px solid var(--border);border-radius:6px;background:var(--color-surface);font-size:12px;padding:6px 9px}.visual-question-nav button.active{background:var(--color-primary);border-color:var(--color-primary);color:#fff}.visual-case{padding:20px;background:var(--color-surface);border:1px solid var(--border);border-radius:12px}.visual-case-heading{display:flex;align-items:center;justify-content:space-between}.visual-case-heading>small{color:var(--muted);font-size:11px}.visual-status{display:inline-flex;align-items:center;gap:6px;font-size:12px}.text-fail{color:var(--color-danger)}.text-error,.text-unknown{color:var(--color-warning)}.text-pass{color:var(--color-success)}.visual-case>h2{font-size:19px;line-height:1.6;letter-spacing:0;margin:14px 0 12px}.visual-reason{font-size:13px;line-height:1.75;color:var(--color-text);margin:0}.visual-reason small{display:block;color:var(--muted);font-size:10px;margin-bottom:4px}.visual-evidence-flow{display:grid;grid-template-columns:1fr 24px 1.2fr;gap:16px;align-items:center;margin:17px 0;padding:16px 0;border-block:1px solid var(--border)}.visual-flow-item{display:flex;gap:14px;align-items:center;text-align:left;border:0;background:none;padding:0;min-width:0;color:var(--color-text)}.visual-flow-item>span:last-child{min-width:0;display:grid;gap:4px}.visual-flow-item small{font-size:11px;color:var(--muted)}.visual-flow-item strong{font-size:14px;font-weight:500;line-height:1.7}.visual-source-names{font-size:11px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:210px}.visual-flow-art{position:relative;width:60px;height:60px;border-radius:15px;background:#f2f3ec;color:#65745a;display:grid;place-items:center;flex-shrink:0}.art-document{position:absolute;right:4px;bottom:4px;color:#959b73;background:#f2f3ec}.visual-flow-arrow{color:#afb6a9}.visual-answer-excerpt{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}.visual-main-actions{display:flex;gap:12px;flex-wrap:wrap}.visual-main-actions button{display:flex;align-items:center;gap:8px}.visual-case-tools{display:flex;gap:22px;justify-content:flex-end;margin-top:14px}.visual-case-tools button,.visual-result-tools button{background:none;border:0;color:var(--muted);font-size:12px;padding:4px 0}.visual-result-tools{display:flex;gap:25px;margin-top:18px;flex-wrap:wrap}.visual-result-tools button{display:flex;gap:7px;align-items:center}.visual-results button:hover:not(:disabled){color:var(--color-text)}.visual-results .primary:hover:not(:disabled){color:#fff}
@media(max-width:650px){.visual-overview{gap:12px;align-items:flex-start}.visual-overview h1{font-size:23px}.visual-ratio strong{font-size:20px}.visual-ratio{font-size:11px}.visual-ratio small{font-size:10px}.visual-result-filters{gap:12px}.visual-question-nav{display:block}.visual-question-nav nav{margin-top:10px}.visual-question-nav button{min-width:35px;padding:6px}.visual-case{padding:17px}.visual-case>h2{font-size:18px}.visual-evidence-flow{grid-template-columns:1fr;gap:12px;margin:18px 0;padding:18px 0}.visual-flow-arrow{transform:rotate(90deg);margin-left:19px}.visual-flow-art{width:50px;height:50px}.visual-source-names{max-width:230px}.visual-result-tools{gap:18px}.visual-case-tools{justify-content:flex-start}.visual-main-actions{gap:8px}.visual-main-actions button{padding:10px 12px;font-size:13px}}
</style>
